import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv3d_fprop(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 C_out,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 D_out,
    .param .u32 H_out,
    .param .u32 W_out
)
{
    // Pointers
    .reg .u64 %in_ptr, %w_ptr, %out_ptr;
    // Thread/block indices
    .reg .u32 %bx, %by, %bz, %bdx, %bdy, %bdz, %tx, %ty, %tz;
    .reg .u32 %ow, %oh, %lz;
    // Params
    .reg .u32 %rN, %rCin, %rCout, %rD, %rH, %rW, %rK, %rDo, %rHo, %rWo;
    .reg .u32 %z_total, %tmp0, %tmp1;
    .reg .u32 %od, %oc, %n;
    .reg .u32 %ci, %kz, %ky, %kx;
    .reg .u32 %iz, %ih, %iw;
    .reg .pred %p;

    // 64-bit temporaries for indexing
    .reg .u64 %n64, %ci64, %oc64, %cin64, %cout64, %d64, %h64, %w64, %k64;
    .reg .u64 %do64, %ho64, %wo64, %iz64, %ih64, %iw64;
    .reg .u64 %t0, %t1, %t2, %t3, %offs, %addr;

    // Accumulators
    .reg .f32 %sum, %aval, %bval;

    // Load params
    ld.param.u64 %in_ptr,   [input_ptr];
    ld.param.u64 %w_ptr,    [weight_ptr];
    ld.param.u64 %out_ptr,  [output_ptr];
    ld.param.u32 %rN,       [N];
    ld.param.u32 %rCin,     [C_in];
    ld.param.u32 %rCout,    [C_out];
    ld.param.u32 %rD,       [D];
    ld.param.u32 %rH,       [H];
    ld.param.u32 %rW,       [W];
    ld.param.u32 %rK,       [K];
    ld.param.u32 %rDo,      [D_out];
    ld.param.u32 %rHo,      [H_out];
    ld.param.u32 %rWo,      [W_out];

    // Compute thread coordinates
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;
    mov.u32 %bz, %ctaid.z;
    mov.u32 %bdx, %ntid.x;
    mov.u32 %bdy, %ntid.y;
    mov.u32 %bdz, %ntid.z;
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %tz, %tid.z;

    mad.lo.u32 %ow, %bx, %bdx, %tx;
    mad.lo.u32 %oh, %by, %bdy, %ty;
    mad.lo.u32 %lz, %bz, %bdz, %tz;

    // Bounds check ow, oh
    setp.ge.u32 %p, %ow, %rWo;
    @%p bra EXIT;
    setp.ge.u32 %p, %oh, %rHo;
    @%p bra EXIT;

    // z_total = N * C_out * D_out
    mul.lo.u32 %z_total, %rN, %rCout;
    mul.lo.u32 %z_total, %z_total, %rDo;
    setp.ge.u32 %p, %lz, %z_total;
    @%p bra EXIT;

    // Decode lz -> (n, oc, od)
    // od = lz % D_out
    rem.u32 %od, %lz, %rDo;
    // tmp0 = lz / D_out
    div.u32 %tmp0, %lz, %rDo;
    // oc = tmp0 % C_out
    rem.u32 %oc, %tmp0, %rCout;
    // n  = tmp0 / C_out
    div.u32 %n, %tmp0, %rCout;

    // sum = 0.0
    mov.f32 %sum, 0f00000000;

    // Prepare 64-bit constants
    cvt.u64.u32 %cin64, %rCin;
    cvt.u64.u32 %cout64, %rCout;
    cvt.u64.u32 %d64, %rD;
    cvt.u64.u32 %h64, %rH;
    cvt.u64.u32 %w64, %rW;
    cvt.u64.u32 %k64, %rK;

    cvt.u64.u32 %n64, %n;
    cvt.u64.u32 %oc64, %oc;

    // ci loop
    mov.u32 %ci, 0;
CI_LOOP:
    setp.ge.u32 %p, %ci, %rCin;
    @%p bra CI_END;

    // kz loop
    mov.u32 %kz, 0;
KZ_LOOP:
    setp.ge.u32 %p, %kz, %rK;
    @%p bra KZ_END;
    add.u32 %iz, %od, %kz;           // iz = od + kz

    // ky loop
    mov.u32 %ky, 0;
KY_LOOP:
    setp.ge.u32 %p, %ky, %rK;
    @%p bra KY_END;
    add.u32 %ih, %oh, %ky;           // ih = oh + ky

    // kx loop
    mov.u32 %kx, 0;
KX_LOOP:
    setp.ge.u32 %p, %kx, %rK;
    @%p bra KX_END;
    add.u32 %iw, %ow, %kx;           // iw = ow + kx

