    cvt.u64.u32 %ci64, %ci;
    cvt.u64.u32 %iz64, %iz;
    cvt.u64.u32 %ih64, %ih;
    cvt.u64.u32 %iw64, %iw;

    // t0 = n*C_in + ci
    mul.lo.u64 %t0, %n64, %cin64;
    add.u64    %t0, %t0, %ci64;
    // t1 = t0*D + iz
    mul.lo.u64 %t1, %t0, %d64;
    add.u64    %t1, %t1, %iz64;
    // t2 = t1*H + ih
    mul.lo.u64 %t2, %t1, %h64;
    add.u64    %t2, %t2, %ih64;
    // t3 = t2*W + iw
    mul.lo.u64 %t3, %t2, %w64;
    add.u64    %t3, %t3, %iw64;
    // offs bytes
    shl.b64    %offs, %t3, 2;
    add.u64    %addr, %in_ptr, %offs;
    ld.global.f32 %aval, [%addr];

    // Load weight value: ((((oc*C_in + ci)*K + kz)*K + ky)*K + kx)
    cvt.u64.u32 %iz64, %kz;          // reuse %iz64 as kz64
    cvt.u64.u32 %ih64, %ky;          // reuse %ih64 as ky64
    cvt.u64.u32 %iw64, %kx;          // reuse %iw64 as kx64

    // t0 = oc*C_in + ci
    mul.lo.u64 %t0, %oc64, %cin64;
    add.u64    %t0, %t0, %ci64;
    // t1 = t0*K + kz
    mul.lo.u64 %t1, %t0, %k64;
    add.u64    %t1, %t1, %iz64;
    // t2 = t1*K + ky
    mul.lo.u64 %t2, %t1, %k64;
    add.u64    %t2, %t2, %ih64;
    // t3 = t2*K + kx
    mul.lo.u64 %t3, %t2, %k64;
    add.u64    %t3, %t3, %iw64;
    // offs bytes
    shl.b64    %offs, %t3, 2;
    add.u64    %addr, %w_ptr, %offs;
    ld.global.f32 %bval, [%addr];

    // sum += aval * bval
    fma.rn.f32 %sum, %aval, %bval, %sum;

    // next kx
    add.u32 %kx, %kx, 1;
    bra KX_LOOP;
KX_END:

    // next ky
    add.u32 %ky, %ky, 1;
    bra KY_LOOP;
KY_END:

    // next kz
    add.u32 %kz, %kz, 1;
    bra KZ_LOOP;
KZ_END:

    // next ci
    add.u32 %ci, %ci, 1;
    bra CI_LOOP;
CI_END:

    // Store output: ((((n*C_out + oc)*D_out + od)*H_out + oh)*W_out + ow)
    cvt.u64.u32 %do64, %rDo;
    cvt.u64.u32 %ho64, %rHo;
    cvt.u64.u32 %wo64, %rWo;
    cvt.u64.u32 %iz64, %od;   // reuse as od64
    cvt.u64.u32 %ih64, %oh;   // reuse as oh64
    cvt.u64.u32 %iw64, %ow;   // reuse as ow64

    // t0 = n*C_out + oc
    mul.lo.u64 %t0, %n64, %cout64;
    add.u64    %t0, %t0, %oc64;
    // t1 = t0*D_out + od
    mul.lo.u64 %t1, %t0, %do64;
    add.u64    %t1, %t1, %iz64;
    // t2 = t1*H_out + oh
    mul.lo.u64 %t2, %t1, %ho64;
    add.u64    %t2, %t2, %ih64;
    // t3 = t2*W_out + ow
    mul.lo.u64 %t3, %t2, %wo64;
    add.u64    %t3, %t3, %iw64;

    shl.b64    %offs, %t3, 2;
    add.u64    %addr, %out_ptr, %offs;
    st.global.f32 [%addr], %sum;

