        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias_flag = bias

        # Parameters to match nn.Conv3d semantics
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size, kernel_size))
        # Initialize as PyTorch Conv3d does: kaiming_uniform_ with a=sqrt(5)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        # bias not supported per constraints above

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be on CUDA device.")
        if x.dtype != torch.float32:
            raise RuntimeError("Only float32 tensors are supported.")
        if not x.is_contiguous():
            raise RuntimeError("Input must be contiguous.")
        if not self.weight.is_contiguous():
            raise RuntimeError("Weight must be contiguous.")
        if self.weight.device != x.device:
            # Allow standard PyTorch module .to(device) semantics; weight will be moved with module
            raise RuntimeError("Model parameters and input must be on the same device.")

        N, Cin, D, H, W = x.shape
        K = self.kernel_size
        Cout = self.out_channels

        Do = D - K + 1
        Ho = H - K + 1
        Wo = W - K + 1
        if Do <= 0 or Ho <= 0 or Wo <= 0:
            raise RuntimeError("Invalid output shape; ensure D,H,W >= kernel_size for this specialization.")

        y = torch.empty((N, Cout, Do, Ho, Wo), device=x.device, dtype=x.dtype)

        z_total = N * Cout * Do
        block_x, block_y, block_z = 16, 8, 4
        grid_x = (Wo + block_x - 1) // block_x
        grid_y = (Ho + block_y - 1) // block_y
        grid_z = (z_total + block_z - 1) // block_z

        module = _get_ptx_module()
        module.launch(
            "conv3d_fprop",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x, self.weight, y,
                i32(N), i32(Cin), i32(Cout),
                i32(D), i32(H), i32(W),
                i32(K),
                i32(Do), i32(Ho), i32(Wo),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

